 const map={schemaVersion:1,mapping:'windows-safe-v1',package:p.version.package,version:p.version.version,variant:p.version.variant,sourceSha256:p.version.sourceSha256,scope:'Decompiled source entries only; raw APK contents remain in the immutable baseline',paths:p.rows.map(r=>({kind:r.kind,component:r.component,path:r.path,logical:r.logical,physical:r.physical,sha256:r.record.sha256,bytes:r.record.bytes,reviewedReplacement:!!r.replacement}))};
